b_allowance = observation(entity='Alice', entity_source='s55', predicate='deduction for herself', predicate_source='s151b')
b_section_151b = observation(entity='Alice', entity_source='s55', predicate='allowed a deduction of $2000 for herself', predicate_source='s151b')
b_section_63d = observation(entity='Alice', entity_source='s56', predicate='deduction falls under section 63(d)', predicate_source='s63d')

@scope('s0') 
def taxable_income_definition_scope(): 
    return True 

@scope('s3') 
def non_itemize_deductions_scope(): 
    return taxable_income_definition_scope 

@scope('s4') 
def standard_deduction_scope(): 
    return non_itemize_deductions_scope 

@scope('s5') 
def standard_deduction_components_scope(): 
    return standard_deduction_scope 

@rule('s5', otherwise=False) 
def standard_deduction_amount(): 
    return (standard_deduction_components_scope and b_allowance and b_section_151b)

@rule('s37', otherwise=False) 
def itemized_deductions_scope(): 
    return taxable_income_definition_scope 

@rule('s38', otherwise=False) 
def itemized_deductions_exclusions(): 
    return (itemized_deductions_scope and b_section_63d)

query = ('Entailment' if itemized_deductions_exclusions else 'Contradiction')
